 5	/**
 6	 * Shared disease behaviour for animals that can both catch and spread infection.
 7	 *
 8	 * @version 2022.03.02
 9	 */
10	public abstract class InfectiousAnimal extends Animal implements Infectable
11	{
12	    public InfectiousAnimal(boolean randomAge, Field field, Location location,
13	                            Class<? extends Animal> speciesClass,
14	                            Set<Class<?>> foodSources,
15	                            Set<Class<?>> killable)
16	    {
17	        super(randomAge, field, location, speciesClass, foodSources, killable);
18	    }
19	
20	    /**
21	     * Infectious animals lose an extra health point when sick and may then
22	     * spread the disease to nearby infectable organisms.
23	     */
24	    protected void applyStepEffects()
25	    {
26	        illness();
27	        if(isAlive()) {
28	            spreadDisease();
29	        }
30	    }
31	
32	    /**
33	     * Decides whether this animal will infect another eligible animal.
34	     */
35	    public void spreadDisease()
36	    {
37	        Field field = getField();
38	        List<Location> adjacent = field.adjacentLocations(getLocation());
39	        Iterator<Location> it = adjacent.iterator();
40	        while(it.hasNext()) {
41	            Location where = it.next();
42	            Object object = field.getObjectAt(where);
43	            if (object != null) {
44	                Organism organism = (Organism) object;
45	                if (organism instanceof Infectable && organism.isAlive()
46	                    && getRand().nextDouble() <= SPREAD_PROBABILITY) {
47	                    Animal target = (Animal) organism;
48	                    target.infect();
49	                }
50	            }
51	        }
52	    }
53	
54	    /**
55	     * Makes the animal take extra damage if it is infected.
56	     */
57	    public void illness()
58	    {
59	        if (getIsInfected()) {
60	            incrementHealth();
61	        }
62	    }
63	}

