  8	/**
  9	 * A class representing shared characteristics of all animals within the simultion.
 10	 * Animals will find food, have a gender and be able to become infected.
 11	 * 
 12	 * @version 2022.03.02
 13	 */
 14	public abstract class Animal extends Organism
 15	{
 16	    // A singleton shared weather object between all organisms and the simulator
 17	    private static final Weather weather = Weather.getWeather();
 18	    // The runtime class used to identify animals of the same species.
 19	    private final Class<? extends Animal> speciesClass;
 20	    // The kinds of organisms this animal can eat.
 21	    private final Set<Class<?>> foodSources;
 22	    // The kinds of organisms this animal can kill.
 23	    private final Set<Class<?>> killable;
 24	    // Gender of the animal
 25	    private boolean isMale;
 26	    // Current health of the animal
 27	    private int currentHealth;
 28	    // Whether the animal is infected
 29	    private boolean isInfected;
 30	    
 31	    /**
 32	     * Create a new animal at location in field.
 33	     * 
 34	     * @param field The field currently occupied.
 35	     * @param location The location within the field.
 36	     */
 37	    public Animal(boolean randomAge, Field field, Location location,
 38	                  Class<? extends Animal> speciesClass,
 39	                  Set<Class<?>> foodSources,
 40	                  Set<Class<?>> killable)
 41	    {
 42	        super(randomAge, field, location);
 43	        this.speciesClass = speciesClass;
 44	        this.foodSources = foodSources;
 45	        this.killable = killable;
 46	        
 47	        if (randomAge) {
 48	            currentHealth = getRand().nextInt(getMaxHealth());
 49	        }
 50	        if (getRand().nextInt(2) == 0) {
 51	            isMale = true;
 52	        }
 53	        else {
 54	            isMale = false;
 55	        }
 56	        
 57	        isInfected = false;
 58	    }
 59	    
 60	    // Abstract methods
 61	    
 62	    /**
 63	     * Abstract method that returns the max health of the animal
 64	     * 
 65	     * @return the animal's max health
 66	     */
 67	    abstract protected int getMaxHealth();
 68	
 69	    // Accessor and mutator methods
 70	
 71	    /**
 72	     * Create an immutable set of organism classes for species configuration.
 73	     *
 74	     * @param classes The organism classes in the set.
 75	     * @return An immutable set containing the given classes.
 76	     */
 77	    protected static Set<Class<?>> classSet(Class<?>... classes)
 78	    {
 79	        return Collections.unmodifiableSet(new LinkedHashSet<>(Arrays.asList(classes)));
 80	    }
 81	    
 82	    /**
 83	     * Returns whether the animal is male
 84	     * 
 85	     * @boolean True if the animal is male, false if animal is female
 86	     */
 87	    protected boolean getGender()
 88	    {
 89	        return isMale;
 90	    }
 91	    
 92	    /**
 93	     * Return the current health of the animal
 94	     * 
 95	     * @return int of the animal's current health
 96	     */
 97	    protected int getCurrentHealth() {
 98	        return currentHealth;
 99	    }
100	    
101	    /**
102	     * Return whether the animal is infected
103	     * 
104	     * @return True if the animal is infected, false if not
105	     */
106	    protected boolean getIsInfected() {
107	        return isInfected;
108	    }
109	    
110	    /**
111	     * Sets the animal to infected state
112	     */
113	    protected void infect() {
114	        isInfected = true;
115	    }
116	
117	    /**
118	     * Return the list of food sources of this animal.
119	     *
120	     * @return The set of classes this animal can eat.
121	     */
122	    protected Set<Class<?>> getFoodSources()
123	    {
124	        return foodSources;
125	    }
126	
127	    /**
128	     * Return the list of classes this animal can kill.
129	     *
130	     * @return The set of classes this animal can kill.
131	     */
132	    protected Set<Class<?>> getKillable()
133	    {
134	        return killable;
135	    }
136	    
137	    // Functional methods
138	
139	    /**
140	     * Animals share the same life-cycle: age, lose health, apply any
141	     * species-specific effects, give birth, and then try to move.
142	     *
143	     * @param newOrganisms A list to receive newborn organisms.
144	     */
145	    public void act(List<Organism> newOrganisms)
146	    {
147	        incrementAge();
148	        incrementHealth();
149	        applyStepEffects();
150	        if(isAlive()) {
151	            giveBirth(newOrganisms);
152	            moveToNextLocation();
153	        }
154	    }
155	    
156	    /**
157	     * Checks if the animal can breed
158	     * 
159	     * @return true if the animal can breed
160	     */
161	    protected boolean canBreed()
162	    {
163	        if (isMale == false)
164	        {
165	            Field field = getField();
166	            List<Location> adjacent = field.adjacentLocations(getLocation());
167	            Iterator<Location> it = adjacent.iterator();
168	            while (it.hasNext())
169	            {
170	                Location where = it.next();
171	                Object thing = field.getObjectAt(where);
172	                if (speciesClass.isInstance(thing))
173	                {
174	                    Animal animal = (Animal) thing;
175	                    return animal.getGender() == true && getAge() >= getBreedingAge();
176	                }
177	            }
178	        }
179	        return false;
180	    }
181	
182	    /**
183	     * Hook for subclasses that need additional work before breeding and moving.
184	     */
185	    protected void applyStepEffects()
186	    {
187	    }
188	    
189	    /**
190	     * A method that will make the animal object search the adjacent squares around it,
191	     * then find and eat an eligible food source.
192	     */
193	    protected Location findFood() {
194	        Field field = getField();
195	        List<Location> adjacent = field.adjacentLocations(getLocation());
196	        Iterator<Location> it = adjacent.iterator();
197	        while(it.hasNext()) {
198	            Location where = it.next();
199	            Object animal = field.getObjectAt(where);
200	            if (animal != null) {                       // makes sure to filter out empty squares
201	                Organism target = (Organism) animal;
202	                if (this.getFoodSources().contains(target.getClass()) && target.isAlive() && getRand().nextDouble() <= weather.getWeatherModifier()) {
203	                    target.setDead();
204	                    //currentHealth = this.getMaxHealth();
205	                    if (this.getFoodSources().contains(target.getClass())) {
206	                        currentHealth = this.getMaxHealth();
207	                    }
208	                }
209	            }
210	        }
211	        return null;
212	    }
213	    
214	    /**
215	     * Decrease this animal's. This could result in the animal's death by hunger.
216	     */
217	    protected void incrementHealth()
218	    {
219	        currentHealth--;
220	        if(currentHealth == 0) {
221	            setDead();
222	        }
223	    }
224	
225	    /**
226	     * Move towards food if possible, otherwise move into any adjacent free cell.
227	     * If no move is possible, the animal dies from overcrowding.
228	     */
229	    private void moveToNextLocation()
230	    {
231	        Location newLocation = findFood();
232	        if(newLocation == null) {
233	            newLocation = getField().freeAdjacentLocation(getLocation());
234	        }
235	
236	        if(newLocation != null) {
237	            setLocation(newLocation);
238	        }
239	        else {
240	            setDead();
241	        }
242	    }
243	}

